import{_ as d,o as i,a as n,b as r}from"./app.DKoEZOcr.js";const o="/ascendc.github.io/pr/5487/assets/conv3d_mkn.BssAgZcn.png",e="/ascendc.github.io/pr/5487/assets/conv3d_mfirst.0HlX0hkE.png",a="/ascendc.github.io/pr/5487/assets/conv3d_nfirst.BxVLXcIj.png",v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"卷积计算","link":"/api/SIMD-API/adv_api/convolution_compute/convolution_compute"},{"text":"Conv3D Tiling侧接口","link":"/api/SIMD-API/adv_api/convolution_compute/Conv3D_Tiling/Conv3d_Tiling"},{"text":"TConv3DApiTiling结构体","link":"/api/SIMD-API/adv_api/convolution_compute/Conv3D_Tiling/TConv3DApiTiling_struct"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/convolution_compute/Conv3D_Tiling/TConv3DApiTiling_struct.md","filePath":"api/SIMD-API/adv_api/convolution_compute/Conv3D_Tiling/TConv3DApiTiling_struct.md","lastUpdated":1787050286000}'),u={name:"api/SIMD-API/adv_api/convolution_compute/Conv3D_Tiling/TConv3DApiTiling_struct.md"};function l(_,t,p,D,s,g){return i(),n("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>TConv3DApiTiling结构体</h1><p>TConv3DApiTiling结构体包含Conv3D算子规格信息及Tiling切分算法的相关参数，被传递给Conv3D核函数（Kernel）侧，用于数据切分、数据搬运和计算等。TConv3DApiTiling结构体的参数说明见<a href="#table18244199192620">表1</a>。</p><p>用户通过调用<a href="GetTiling.html">GetTiling</a>接口获取TConv3DApiTiling结构体，具体流程请参考<a href="Conv3D_Tiling_usage.html">Conv3D Tiling使用说明</a>。当前暂不支持用户自定义配置TConv3DApiTiling结构体中的参数。</p><p><strong>表1</strong> TConv3DApiTiling结构说明</p><p><span id="table18244199192620"></span></p><table><thead><tr><th>参数名称</th><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>groups</td><td>uint32_t</td><td>预留参数，当前仅支持为1。</td></tr><tr><td>singleCoreDo</td><td>uint64_t</td><td>单核上处理的Dout大小。</td></tr><tr><td>singleCoreCo</td><td>uint32_t</td><td>单核上处理的Cout大小。</td></tr><tr><td>singleCoreM</td><td>uint64_t</td><td>单核上处理的M大小。</td></tr><tr><td>orgDo</td><td>uint64_t</td><td>Conv3D计算中原始Dout大小。</td></tr><tr><td>orgCo</td><td>uint32_t</td><td>Conv3D计算中原始Cout大小。</td></tr><tr><td>orgHo</td><td>uint64_t</td><td>Conv3D计算中原始Hout大小。</td></tr><tr><td>orgWo</td><td>uint64_t</td><td>Conv3D计算中原始Wout大小。</td></tr><tr><td>orgCi</td><td>uint32_t</td><td>Conv3D计算中原始Cin大小。</td></tr><tr><td>orgDi</td><td>uint64_t</td><td>Conv3D计算中原始Din大小。</td></tr><tr><td>orgHi</td><td>uint64_t</td><td>Conv3D计算中原始Hin大小。</td></tr><tr><td>orgWi</td><td>uint64_t</td><td>Conv3D计算中原始Win大小。</td></tr><tr><td>kernelD</td><td>uint32_t</td><td>Conv3D计算中卷积核原始kernel D维度大小。</td></tr><tr><td>kernelH</td><td>uint32_t</td><td>Conv3D计算中卷积核原始kernel H维度大小。</td></tr><tr><td>kernelW</td><td>uint32_t</td><td>Conv3D计算中卷积核原始kernel W维度大小。</td></tr><tr><td>strideD</td><td>uint32_t</td><td>Conv3D计算中Stride D维度大小。</td></tr><tr><td>strideH</td><td>uint32_t</td><td>Conv3D计算中Stride H维度大小。</td></tr><tr><td>strideW</td><td>uint32_t</td><td>Conv3D计算中Stride W维度大小。</td></tr><tr><td>dilationD</td><td>uint32_t</td><td>Conv3D计算中Dilation D维度大小。</td></tr><tr><td>dilationH</td><td>uint32_t</td><td>Conv3D计算中Dilation H维度大小。</td></tr><tr><td>dilationW</td><td>uint32_t</td><td>Conv3D计算中Dilation W维度大小。</td></tr><tr><td>padHead</td><td>uint32_t</td><td>Conv3D计算中Padding D维度Head方向大小。</td></tr><tr><td>padTail</td><td>uint32_t</td><td>Conv3D计算中Padding D维度Tail方向大小。</td></tr><tr><td>padUp</td><td>uint32_t</td><td>Conv3D计算中Padding H维度Up方向大小。</td></tr><tr><td>padDown</td><td>uint32_t</td><td>Conv3D计算中Padding H维度Down方向大小。</td></tr><tr><td>padLeft</td><td>uint32_t</td><td>Conv3D计算中Padding W维度Left方向大小。</td></tr><tr><td>padRight</td><td>uint32_t</td><td>Conv3D计算中Padding W维度Right方向大小。</td></tr><tr><td>mL0</td><td>uint32_t</td><td>L0上单次处理的M大小。</td></tr><tr><td>kL0</td><td>uint32_t</td><td>L0上单次处理的K大小。</td></tr><tr><td>nL0</td><td>uint32_t</td><td>L0上单次处理的N大小。</td></tr><tr><td>kAL1</td><td>uint32_t</td><td>L1上Input K的实际大小，等于Cin1InL1 * KH * KW * C0，Cin1InL1是KD * Cin1合轴之后Tiling切分的大小。</td></tr><tr><td>kBL1</td><td>uint32_t</td><td>L1上Weight K的实际大小，等于Cin1InL1 * KH * KW * C0，Cin1InL1是KD * Cin1合轴之后Tiling切分的大小。</td></tr><tr><td>nBL1</td><td>uint32_t</td><td>L1上Weight载入Cout维度的实际数据大小。</td></tr><tr><td>mAL1</td><td>uint32_t</td><td>L1上Input载入M的实际数据大小。</td></tr><tr><td>al1FullLoad</td><td>uint8_t</td><td>Input数据在L1 Buffer是否全载。<br><br>0：Input数据在L1 Buffer上不全载。<br><br>1：Input数据在L1 Buffer上全载。</td></tr><tr><td>bl1FullLoad</td><td>uint8_t</td><td>Weight数据在L1 Buffer是否全载。<br><br>0：Weight数据在L1 Buffer上不全载。<br><br>1：Weight数据在L1 Buffer上全载。</td></tr><tr><td>iterateMNOrder</td><td>uint8_t</td><td>输出结果矩阵Output时，M轴和N轴的输出顺序。<br><br>0：优先输出M方向。先输出M方向，再输出N方向，请见图2。<br><br>1：优先输出N方向。先输出N方向，再输出M方向，请见图3。<br><br>M由Hout和Wout组成，M方向的输出顺序为，先输出Wout方向，再输出Hout方向。</td></tr><tr><td>biasFullLoadFlag</td><td>uint8_t</td><td>Bias是否全载进L1 Buffer。<br><br>0：否，单核内单次载入Bias大小等于单次矩阵乘N方向的大小nL0。<br><br>1：是，单核内的Bias一次全载。</td></tr></tbody></table><p>注：上述的M轴为卷积正向操作过程中的输入Input在img2col展开后的纵轴，数值上等于Hout * Wout；K为输入Input在img2col展开后的横轴，数值上等于KD*C1*KH*KW*C0；KD/KH/KW为Weight的Depth、Height、Width，即kernelD/kernelH/kernelW的简写；N为Weight的Cout，具体请见图1。</p><p><strong>图1</strong> 卷积3D正向MKN示意图<br><img src="'+o+'" alt title="卷积3D正向MKN示意图"></p><p><strong>图2</strong> 卷积3D正向MFirst示意图<br><img src="'+e+'" alt title="卷积3D正向MFirst示意图"></p><p><strong>图3</strong> 卷积3D正向NFirst示意图<br><img src="'+a+'" alt title="卷积3D正向NFirst示意图"></p></article></div>',1)])])}const c=d(u,[["render",l]]);export{v as __pageData,c as default};
